import { Component, createMemo } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";

export interface AgeIconProps {
	class: string;
	ageId: string;
	apexTooltip?: boolean;
	framedIcons?: boolean;
}

export const AgeIcon: Component<AgeIconProps> = (props) => {
	// TODO: These are stubs - actual age icons should be set in the xml
	const ageName = createMemo(() => props.ageId.replace("AGE_", ""));
	const ageText = createMemo(() => `LOC_UI_CREATE_GAME_${ageName()}`);
	const ageApexText = createMemo(() => `${ageText()}_APEX`);
	const ageIcons = createMemo(() => `url('blp:city_${ageName().toLowerCase()}')`);
	const framedAgeIcon = createMemo(() => `url('blp:city_${ageName().toLowerCase()}_128x128')`);

	return (
		<Tooltip.Text
			bodyClass="flex flex-row justify-center"
			text={props.apexTooltip ? ageApexText() : ageText()}
		>
			<Icon
				class={props.class}
				name={props.framedIcons ? framedAgeIcon() : ageIcons()}
			/>
		</Tooltip.Text>
	);
};
